style.content:
/* Centred on the screen, above everything */
.popup {
  position: fixed;
  inset: 0;
  z-index: 1000;
  height: fit-content;
  margin: auto;
}

.backdrop {
  position: fixed;
  inset: 0;
  z-index: 999;
  background: rgb(20 18 30 / 0.5);
  backdrop-filter: blur(2px);
}

style.hiddenContent:
/* Preview frame shared by every view (from Lunch and Learn Simple's simple.css).
   Nothing in here is part of any demo. */
:root {
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: clamp(15px, 0.55vw + 9px, 21px);
  color: #1c1b22;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
}

:focus-visible {
  outline: 3px solid #1f6feb;
  outline-offset: 2px;
}

/* The demo area fills the preview. */
.stage {
  position: relative;
  height: 100vh;
  overflow: hidden;
  background: #fff;
}

/* Note shown by unsupported.js when the browser lacks the feature. */
.unsupported {
  position: absolute;
  left: 0.8rem;
  bottom: 0.8rem;
  z-index: 100;
  display: flex;
  align-items: baseline;
  gap: 0.45rem;
  max-width: min(26rem, calc(100% - 1.6rem));
  margin: 0;
  padding: 0.35rem 0.75rem;
  font-size: 0.72rem;
  line-height: 1.4;
  color: #b42318;
  background: rgb(253 233 230 / 0.95);
  border: 1px solid #f1b8b0;
  border-radius: 0.6rem;
  pointer-events: none;
}

.unsupported::before {
  content: '';
  flex: none;
  width: 0.45rem;
  height: 0.45rem;
  background: #e5372b;
  border-radius: 50%;
}

.unsupported b {
  color: #8f1d14;
}

/* Looks only: nothing but the room the exercise needs, the same in every view. */
.stage {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  align-content: start;
  justify-content: center;
  gap: 0.8rem;
  padding: 1.6rem 1.4rem;
  background: #f8f6f1;
}

/* The buttons on the page, the ones that open a popup */
.share-button,
.stage > button {
  flex: none;
  padding: 0.5rem 1rem;
  font: inherit;
  font-weight: 700;
  color: #fff;
  background: #1c1b22;
  border: 0;
  border-radius: 0.6rem;
  cursor: pointer;
}

/* The popup itself */
.popup {
  width: 24rem;
  padding: 1.4rem 1.5rem;
  color: #1c1b22;
  background: #fff;
  border: 0;
  border-radius: 1.1rem;
  box-shadow: 0 30px 70px -20px rgb(0 0 0 / 0.5);
}

.popup h3 {
  margin: 0 0 0.3rem;
  font-size: 1.25rem;
}

.popup p {
  margin: 0 0 1rem;
  color: #6f6c7d;
}

.popup input {
  box-sizing: border-box;
  width: 100%;
  padding: 0.6rem 0.8rem;
  font: inherit;
  font-size: 0.9rem;
  color: #474553;
  background: #f5f2ec;
  border: 1px solid #e4dfd4;
  border-radius: 0.6rem;
}

.popup-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 1.2rem;
}

.popup-actions button {
  padding: 0.5rem 1rem;
  font: inherit;
  font-weight: 700;
  color: #1c1b22;
  background: #fff;
  border: 1px solid #cbc4b4;
  border-radius: 0.6rem;
  cursor: pointer;
}

.popup-actions .primary {
  color: #fff;
  background: #4636c9;
  border-color: #4636c9;
}

/* Decoration only: a short fade-in on opening */
.popup {
  animation: pop-in 0.2s ease-out;
}

.popup::backdrop {
  animation: fade-in 0.2s ease-out;
}

@keyframes pop-in {
  from {
    opacity: 0;
    scale: 0.96;
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
}

script.content:
const backdrop = document.querySelector('.backdrop');
// On a page with dozens of popups neither of these is known in advance: both the popup
// and the control it was opened from have to be worked out from the click.
let openPopup = null;
let opener = null;

function open(popup, trigger) {
  if (openPopup) close();
  openPopup = popup;
  opener = trigger;
  popup.hidden = false;
  backdrop.hidden = false;
  trigger.setAttribute('aria-expanded', 'true');
  // Click outside (on the backdrop) or Escape closes it
  backdrop.addEventListener('click', close);
  document.addEventListener('keydown', onKeyDown);
}

function close() {
  if (!openPopup) return;
  openPopup.hidden = true;
  backdrop.hidden = true;
  opener.setAttribute('aria-expanded', 'false');
  backdrop.removeEventListener('click', close);
  document.removeEventListener('keydown', onKeyDown);
  // Give focus back to the control this popup was opened from. Without it focus falls back
  // to <body> and the next Tab starts at the top of the page. A popover does it on its own,
  // for any invoker, because the browser knows which one it was.
  if (openPopup.contains(document.activeElement)) opener.focus();
  openPopup = null;
  opener = null;
}

function onKeyDown(event) {
  if (event.key === 'Escape') close();
}

// One listener for the whole page: the event tells us which control was used and, through
// its aria-controls, which popup it opens. The same code serves any number of them.
document.addEventListener('click', (event) => {
  const trigger = event.target.closest('[aria-controls]');
  if (!trigger) {
    // a Close button inside the popup
    if (event.target.closest('.close')) close();
    return;
  }
  const popup = document.getElementById(trigger.getAttribute('aria-controls'));
  // The same control toggles: a second click (or Enter) closes it again
  popup === openPopup ? close() : open(popup, trigger);
});
